#!/usr/bin/env bash # Omega Swarm — Data Backup Script # Backs up data/store.json to S3 or local backup directory # Usage: ./scripts/backup.sh [s3|local] set -euo pipefail BACKUP_TYPE=${1:-local} DATA_FILE=/app/data/store.json BACKUP_DIR=${BACKUP_DIR:-./backups} S3_BUCKET=${S3_BUCKET:-} TIMESTAMP=$(date +%Y%m%d_%H%M%S) BACKUP_NAME=store-${TIMESTAMP}.json echo [BACKUP] Starting backup at $TIMESTAMP if [[ ! -f $DATA_FILE ]]; then echo [BACKUP] ERROR: Data file not found at $DATA_FILE exit 1 fi if [[ $BACKUP_TYPE == local ]]; then mkdir -p $BACKUP_DIR cp $DATA_FILE $BACKUP_DIR/$BACKUP_NAME echo [BACKUP] Local backup created: $BACKUP_DIR/$BACKUP_NAME # Keep only last 30 backups find $BACKUP_DIR -name store-*.json -type f | sort -r | tail -n +31 | xargs -r rm -f echo [BACKUP] Cleaned old backups (kept last 30) elif [[ $BACKUP_TYPE == s3 ]]; then if ! command -v aws &> /dev/null; then echo [BACKUP] ERROR: AWS CLI not installed exit 1 fi if [[ -z $S3_BUCKET ]]; then echo [BACKUP] ERROR: S3_BUCKET environment variable not set exit 1 fi aws s3 cp $DATA_FILE s3://$S3_BUCKET/backups/$BACKUP_NAME echo [BACKUP] S3 backup created: s3://$S3_BUCKET/backups/$BACKUP_NAME else echo [BACKUP] ERROR: Backup type must be 'local' or 's3' exit 1 fi echo [BACKUP] Backup completed successfully